            Paragraph(Text("For the actual lattice construction use A=actualVertexAlgebra(D), its original state-field Y, vacuum and charge-sensitive translation. For charges alpha,beta and arbitrary oscillator descendants u,v, canonical(D,alpha,beta,u)_n v equals the finite sum of (-1)^(n+j+1)/j! times sectorT(D,alpha+beta)^j applied to canonical(D,beta,alpha,v)_(n+j) u. The equality beta+alpha=alpha+beta identifies the output label. Inclusion into the full carrier, single_canonical, and induction from single_sectorT transport the entire translation power, then projection recovers the charge-sector statement. This exact specialization is compiled transient evidence and introduces no orphan binding declaration. It preserves the actual canonical field rather than replacing it by a cocycle model.")),
            Paragraph(Text("No positivity, nonsingularity, homogeneous or primary restriction is imposed. Rank zero, zero states, the vacuum and arbitrary translation descendants remain in scope. This standard algebraic law is not a claim of literature novelty, coherent tensor-category braiding, a Monster realization, analytic CFT, string theory or AdS/CFT completion.")),
            Describe.Lean(DescribeId.Create("statefield-skew-creation-coeff"), DeclarationHandle.Create(Prefix + "creation_coeff"), H("The entire vacuum creation series"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source), Blocks(Paragraph(Text("Induction from translation covariance and creation proves the factorial divided powers for every natural degree."))), DescribeRole.Theorem),
