            Describe.Lean(DescribeId.Create("statefield-skew-reversal-finite"), DeclarationHandle.Create(Prefix + "reversal_finite"), H("Each coefficient has finite convolution support"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source), Blocks(Paragraph(Text("The order of the original Hahn series bounds the natural summation index. Zero terms stay zero under all powers of translation."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("statefield-skew-reversal-bounded"), DeclarationHandle.Create(Prefix + "reversal_bounded"), H("The output retains a lower support bound"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source), Blocks(Paragraph(Text("Every coefficient below the original series order vanishes."))), DescribeRole.Theorem),
