            Describe.Lean(DescribeId.Create("statefield-skew-skew-symmetry"), DeclarationHandle.Create(Prefix + "skew_symmetry"), H("All-state skew symmetry"), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source), Blocks(Paragraph(Text("For arbitrary signed n and arbitrary states, a_n b is the finite sum of (-1)^(n+j+1)/j! times T^j(b_(n+j) a). Equivalently Y(a,z)b=exp(zT)Y(b,-z)a as Hahn series."))), DescribeRole.Theorem),
